import{X as e,Z as t,t as n,ut as r}from"./chunks/framework.es-12sf8.js";var i=JSON.parse(`{"title":"Migrate from V2","description":"","frontmatter":{},"headers":[],"relativePath":"usage/migration.md","filePath":"en/usage/migration.md","lastUpdated":1787300168000}`),a={name:`usage/migration.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="migrate-from-v2" tabindex="-1">Migrate from V2 <a class="header-anchor" href="#migrate-from-v2" aria-label="Permalink to “Migrate from V2”">​</a></h1><p>The v3 version of Sync Engine is released on August 7, 2026, its former name is &quot;WebDAV Sync&quot;, which has been in production for months. The v2 to v3 transition is a complete rewrite focusing on modularity and performance; many things, <strong>including remote file structure, storage schema, encryption formula, and plugin settings have changed completely</strong>. A migration is required for all users that are still using v2.</p><h2 id="automatic-migration" tabindex="-1">Automatic Migration <a class="header-anchor" href="#automatic-migration" aria-label="Permalink to “Automatic Migration”">​</a></h2><p>In the last two versions of WebDAV Sync (v2.5.12 and v2.5.13) contain a complete migration routine to seamlessly transform you from WebDAV Sync to Sync Engine.</p><p>At each startup, the plugin makes request to GitHub API to confirm the existence of repo <code>hesprs/sync-engine</code>, it treats the existence of this repo as the signal of the release of Sync Engine. If this repo exists, the plugin will open up a modal to prompt you to migrate to Sync Engine. The modal has two three options:</p><ul><li><strong>Proceed</strong>: the migration will start</li><li><strong>Cancel</strong>: the migration will be prompted again on next plugin startup</li><li><strong>Never show again</strong>: the migration will be silenced forever and WebDAV Sync remains fully functional as before. You can access the migration routine from plugin settings.</li></ul><p>If you started migration, it will perform the following:</p><ol><li>Launch another turn of syncing to ensure your vault&#39;s state is aligned with the remote.</li><li>Read-only traverse the WebDAV to obtain the necessary <code>Etag</code> of each file, which is used by Sync Engine to identify file uniqueness.</li><li>Access Sync Engine module source <code>https://sync.consensia.cc/modules.json</code> to download necessary Sync Engine modules for you. The modules downloaded depends on the functions you used in WebDAV Sync: <ul><li>Supported i18n modules if you are a non-English user.</li><li>Encryption module if you enabled encryption.</li><li>Smart merge module if your conflict strategy is &quot;Smart merge&quot;.</li></ul></li><li>Copy and transform existing sync records to Sync Engine store.</li><li>Only when all above steps succeed, local records will be deleted. And you will be prompted to Download Sync Engine from Obsidian plugin store.</li></ol><p>If any of the 1-4 step fails, the migration will be rolled back immediately, no data will be lost.</p><p>Due to the revamped encryption schema, <strong>WebDAV Sync encrypted files will be no longer accessible by Sync Engine&#39;s Encryption module</strong>. So if you are using Encryption, you are required to delete remote base directory and <strong>re-sync your vault in Sync Engine</strong>. If you are not using encryption, you simply need to download Sync Engine from Obsidian module store and disable WebDAV Sync, then everything is done.</p><p>For seamless migration, <strong>Sync Engine&#39;s most ingenious feature <em>Anchored Asymmetric Storage</em> is disabled by default</strong> if you are not using encryption (when encryption is enabled, this is left enabled since you will need to re-sync the entire vault anyway). You can enable that and use Sync Engine&#39;s built-in migration feature to transform your vault, then your every sync will be accelerated by this technology.</p><h3 id="version-2-5-14" tabindex="-1">Version <code>2.5.14</code> <a class="header-anchor" href="#version-2-5-14" aria-label="Permalink to “Version 2.5.14”">​</a></h3><p>Previous versions may have performance issue when encountering large vaults, which may lead to migration failure. This is a design defect and is patched in version <code>2.5.14</code>. If you find your migration failing in <strong>step 5</strong> with errors like <code>net::ERR_INSUFFICIENT_RESOURCES</code>, please <a href="https://github.com/hesprs/sync-engine/releases/download/2.5.14/main.js" target="_blank" rel="noreferrer">click here</a> to download the patched version, replace <code>&lt;your vault&gt;/.obsidian/plugins/webdav-sync/main.js</code>, and try migration again.</p><h2 id="manual-migration" tabindex="-1">Manual Migration <a class="header-anchor" href="#manual-migration" aria-label="Permalink to “Manual Migration”">​</a></h2><p>If you need a more transparent migration process to see what is going on around your data. You can choose manual migration, you need to perform all the following:</p><ol><li>Go into Obsidian, use WebDAV Sync to sync all your devices to ensure they have aligned copies of your data. If it shows the migration prompt, choose &quot;cancel&quot; directly.</li><li>Disable and delete WebDAV Sync on every devices.</li><li>Install Sync Engine from Obsidian plugin store.</li><li>Install the <code>WebDAV</code> module from the module management page in Sync Engine settings, configure your account on every devices.</li><li>If you previously <strong>enabled encryption</strong>, please download the Encryption module and configure the encryption password. The manually delete the remote base directory on your WebDAV management UI. Choose one of your devices with better internet connection to sync your encrypted full vault to the remote.</li><li>If you are not using encryption previously, <strong>go to Sync Engine settings and disable &quot;Asymmetric storage&quot;, you do not need to delete any data anywhere.</strong></li><li>Perform sync on all other devices, Sync Engine should scan the remote folder and picks up the aligned state, populates its internal records only and shows &quot;Already synced&quot;.</li></ol>`,16)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};